ion": null, "id": 3, "type": "page_footer"}, {"bbox": [{"coord": [667, 1007, 1124, 1060], "page_id": 8}], "content": "The Treasury Bulletin is for sale by the Superintendent of Documents,", "description": null, "id": 0, "type": "text"}, {"bbox": [{"coord": [574, 1058, 1221, 1085], "page_id": 8}], "content": "U.S. Government Printing Office, Washington, D.C. 20402", "description": null, "id": 1, "type": "text"}, {"bbox": [{"coord": [606, 1080, 1192, 1133], "page_id": 8}], "content": "Subscription per year $13.50 domestic, $17.00 foreign. Single copy price varies.", "description": null, "id": 2, "type": "text"}, {"bbox": [{"coord": [1472, 39, 1500, 102], "page_id": 9}], "content": "", "description": null, "id": 0, "type": "page_number"}, {"bbox": [{"coord": [0, 41, 193, 131], "page_id": 9}], "content": "April 1972", "description": null, "id": 1, "type": "page_header"}, {"bbox": [{"coord": [600, 248, 843, 309], "page_id": 9}], "content": "CONTENTS", "description": null, "id": 2, "type": "title"}, {"bbox": [{"coord": [71, 411, 1382, 1992], "page_id": 9}], "content": "<table><tr><td>Treasury financing operations.</td><td>II</td></tr><tr><td>Federal fiscal operations.</td><td>1</td></tr><tr><td>Federal obligations.</td><td>13</td></tr><tr><td>Account of the Treasurer of the United States.</td><td>17</td></tr><tr><td>Monetary statistics.</td><td>20</td></tr><tr><td>Federal debt.</td><td>21</td></tr><tr><td>Public debt operations.</td><td>29</td></tr><tr><td>United States savings bonds.</td><td>62</td></tr><tr><td>United States savings notes.</td><td>66</td></tr><tr><td>Ownership of Federal securities.</td><td>67</td></tr><tr><td>Treasury survey of ownership.</td><td>69</td></tr><tr><td>Market quotations on Treasury securities.</td><td>76</td></tr><tr><td>Average yields of long-term bonds.</td><td>79</td></tr><tr><td>Exchange Stabilization Fund</td><td>81</td></tr><tr><td>International financial statistics.</td><td>83</td></tr><tr><td>Capital movements.</td><td>89</td></tr>